async function envoyerBrut(texte) {
  const r = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST", headers:{"Content-Type":"application/json"}, body:texte});
  const corps = await r.json();
  return {statut:r.status, erreur:corps.erreur === undefined ? null : corps.erreur};
}

