async function classerInscription(atelierId, nom) {
  const r = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({atelierId:atelierId,nom:nom})});
  const etats = {201:"acceptée-fictive",409:"complet",404:"inconnu",422:"invalide"};
  return {statut:r.status, etat:etats[r.status]};
}

