async function inscrireValide(id, nom) {
  if (!Number.isInteger(id) || id < 1 || typeof nom !== "string" || nom.trim().length < 1 || nom.trim().length > 40) { return {etat:"invalide-local",statut:null}; }
  const r = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({atelierId:id,nom:nom.trim()})});
  return {etat:r.ok ? "acceptée" : "refusée",statut:r.status};
}

